WITH lines AS (SELECT id, level, status_code, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, v) SELECT id, level, status_code, attr_key, v, LAG(status_code) OVER (PARTITION BY attr_key ORDER BY status_code, id, attr_key) AS prev_status_code, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY status_code, id, attr_key) AS row_seq FROM lines WHERE status_code = 267;
